    let export_snapshot: Rc<RefCell<Option<(WmPreset, i32)>>> = Rc::new(RefCell::new(None));
    // v0.8.120 (design-sweep Y43): is the toast currently on screen a LOGGED event (so its × may
    // decrement the unread badge) or a transient one (so it must not)? See `show_transient_toast`.
    let toast_counts_unread: Rc<Cell<bool>> = Rc::new(Cell::new(false));
    // v0.8.120 (design-sweep O6): the folder the LIVE toast's Resume belongs to — the transient half
