    let toast_jump_dir: Rc<RefCell<String>> = Rc::new(RefCell::new(String::new()));
    let notif_unread = Rc::new(Cell::new(0i32));
    let toast_left = Rc::new(Cell::new(0i32)); // v0.8.155 (D2): MILLISECONDS remaining, not ticks
    // v0.8.155 (D2, owner ruling 2): the previous tick's Instant — `step_notifs` spends the real
