    let scan_done = Arc::new(Mutex::new(None::<ScanDone>));
    let early_scan = Arc::new(Mutex::new(None::<ScanDone>));
    let photo_open_id = Arc::new(AtomicU64::new(0));
    let photo_presented = Arc::new((Mutex::new(0u64), std::sync::Condvar::new()));
    let scan_id = Arc::new(AtomicU64::new(0));
