    // passed through Slint) + the saved presets + their name model.
    let export_image_path = Rc::new(RefCell::new(String::new()));
    let wm_cache: Rc<RefCell<Option<(Vec<u8>, u32, u32)>>> = Rc::new(RefCell::new(None));
