    // family (or a default), cached, and cleared when the family changes.
    let ui_font: Rc<RefCell<Option<(Vec<u8>, u32)>>> = Rc::new(RefCell::new(None));
    // Installed-font picker: family → (file, face index), enumerated once on a background thread.
    let font_map: Rc<RefCell<HashMap<String, (PathBuf, u32)>>> = Rc::new(RefCell::new(HashMap::new()));
    let (font_list_tx, font_list_rx) = channel::<(Vec<String>, HashMap<String, (PathBuf, u32)>)>();
    std::thread::spawn(move || {
        let _ = font_list_tx.send(enumerate_fonts());
    });
