            if !armed.get() || started.get() {
                return;
            }
            // Walk the families in the UI list's order (the model IS that order).
            let fams: Vec<(String, PathBuf, u32)> = {
                let map = fmap.borrow();
                model
                    .iter()
                    .filter_map(|r| {
                        map.get(r.name.as_str()).map(|(p, i)| (r.name.to_string(), p.clone(), *i))
                    })
                    .collect()
            };
