            // apply_theme_transform does — an untransformed bake would visibly mismatch the
            // un-swapped rows on the owner's custom Dell profile.
            let dst = awz.upgrade().map(|a| a.get_output_gamut()).unwrap_or(0);
            let color =
                falcon_color::transform_rgb8([0xf7, 0xf7, 0xf7], Gamut::Srgb, Gamut::from_i32(dst));
