    let wm_photo_cm = Rc::new(Cell::new(0u64));
    let wm_preview_dirty = Rc::new(Cell::new(false));
    // v0.3.60: last-seen content signature of the watermark raster, so the overlay Image is rebuilt
    // only when the logo/text actually changes (not on every position drag).
    let wm_logo_sig = Rc::new(Cell::new(0u64));
    // N20: the sheet-open sample decode runs OFF-THREAD (a 45 MP PNG/TIFF has no scaled decode
    // path and froze the open for seconds). Worker → (request id, aspect, sample, source gamut) →
    // tick drain; `wm_sample_req` tags the latest open so a superseded decode is discarded.
    let wm_sample_slot: Arc<Mutex<Option<tick::WmSampleDrop>>> = Arc::new(Mutex::new(None));
    let wm_sample_req = Arc::new(AtomicU64::new(0));
