        // string over.
        assert_eq!(platform::empty_confirm_title(1), "file in ./Rejected → Recycle Bin");
        assert_eq!(platform::empty_confirm_title(8), "files in ./Rejected → Recycle Bin");
        assert_eq!(platform::empty_confirm_title(0), "files in ./Rejected → Recycle Bin");
